// ============================================================================
//  MULTI-CLINICA
//  Cada cita se evalua con la zona horaria de SU clinica y se envia desde el
//  numero de WhatsApp de SU clinica. Dar de alta una clinica nueva = insertar
//  una fila en la tabla clinicas. Este codigo NO se toca nunca mas.
// ============================================================================

// AVISO: las clinicas hay que leerlas POR EL NOMBRE del nodo.
// $input aqui devuelve las CITAS (el nodo inmediatamente anterior).
const clinicas = new Map(
  $('Cargar clinicas').all()
    .map(item => item.json || {})
    .filter(c => c.id)
    .map(c => [c.id, c])
);

const ZONA_POR_DEFECTO      = 'Europe/Madrid';
const ESPERA_POST_CITA_MIN  = 60;

// Fuente de verdad: la duracion real que guardo el workflow 01 en la columna
// duracion_minutos. La tabla de abajo es solo un respaldo por si alguna fila
// antigua no la tiene.
const DURACION_POR_DEFECTO = 60;
const DURACIONES_TRATAMIENTO = [
  { patrones: ['revision', 'revision dental', 'revisao', 'checkup', 'check-up'], minutos: 30 },
  { patrones: ['limpieza', 'limpeza', 'nettoyage', 'cleaning'], minutos: 45 },
  { patrones: ['blanqueamiento', 'branqueamento', 'blanchiment', 'whitening'], minutos: 90 },
  { patrones: ['empaste', 'obturacion', 'plombage', 'filling'], minutos: 60 },
  { patrones: ['ortodoncia', 'ortodontia', 'orthodontie', 'orthodontics'], minutos: 60 }
];

const normalizarTexto = texto => (texto || '').toString().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

const duracionCita = row => {
  const guardada = Number(row.duracion_minutos);
  if (Number.isFinite(guardada) && guardada > 0) return guardada;
  const valor = normalizarTexto(row.tratamiento);
  const encontrado = DURACIONES_TRATAMIENTO.find(item =>
    item.patrones.some(patron => valor.includes(normalizarTexto(patron))));
  return encontrado ? encontrado.minutos : DURACION_POR_DEFECTO;
};

// Supabase devuelve booleanos reales. Aceptamos tambien los textos 'no'/'false'
// que venian de Google Sheets, por si queda alguna fila migrada a mano.
const pendienteDeSolicitar = v => v === false
  || v === null
  || v === undefined
  || ['no', 'false', ''].includes(v.toString().toLowerCase().trim());

const normHora = h => {
  if (h === null || h === undefined || h === '') return '';
  if (typeof h === 'number') {
    const totalMin = h >= 0 && h < 1
      ? Math.round(h * 24 * 60)
      : Math.round(Math.floor(h) * 60 + (h % 1) * 60);
    return Math.floor(totalMin / 60).toString().padStart(2, '0') + ':' + (totalMin % 60).toString().padStart(2, '0');
  }
  let v = h.toString().trim().toLowerCase()
    .replace(/\s*(horas|hora|hrs?|h)\s*$/i, '').replace('.', ':').trim();
  if (/^\d{1,2}$/.test(v)) return v.padStart(2, '0') + ':00';
  if (/^\d{1,2}:\d{2}:\d{2}$/.test(v)) v = v.slice(0, 5);
  if (/^\d{1,2}:\d{1,2}$/.test(v)) {
    const parts = v.split(':');
    return parts[0].padStart(2, '0') + ':' + parts[1].padStart(2, '0');
  }
  return v;
};

// La columna fecha es de tipo date: Supabase la devuelve como 'YYYY-MM-DD'.
const normFecha = f => {
  if (!f) return '';
  const v = f.toString().trim();
  const es = v.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (es) return es[3] + '-' + es[2] + '-' + es[1];
  const iso = v.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return iso[1] + '-' + iso[2] + '-' + iso[3];
  return v;
};

// El desfase horario depende de la zona de la clinica Y de la fecha (horario
// de verano). Por eso recibe la zona como parametro y no usa una constante.
const offsetClinica = (zona, fechaStr, horaStr) => {
  const probe = new Date(fechaStr + 'T' + horaStr + ':00Z');
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zona, hour: '2-digit', minute: '2-digit', timeZoneName: 'longOffset'
  }).formatToParts(probe);
  const tz = (parts.find(p => p.type === 'timeZoneName') || {}).value || 'GMT+00:00';
  const m = tz.match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/);
  if (!m) return '+00:00';
  return m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00').padStart(2, '0');
};

const finCita = (row, zona) => {
  const fecha = normFecha(row.fecha || '');
  const hora  = normHora(row.hora || '');
  if (!fecha || !hora) return null;
  const inicio = new Date(fecha + 'T' + hora + ':00' + offsetClinica(zona, fecha, hora));
  if (Number.isNaN(inicio.getTime())) return null;
  return new Date(inicio.getTime() + duracionCita(row) * 60 * 1000);
};

const ahora = new Date();

return $input.all()
  .map(item => item.json || {})
  .map(row => ({ row, clinica: clinicas.get(row.clinica_id) }))
  .filter(({ row, clinica }) => {
    // Sin clinica, desactivada o sin numero de WhatsApp no se envia nada.
    if (!clinica || clinica.activo === false) return false;
    if (!clinica.telefono_whatsapp_id) return false;

    const zona     = clinica.zona_horaria || ZONA_POR_DEFECTO;
    const estado   = (row.estado || '').toString().toLowerCase().trim();
    const telefono = (row.telefono || '').toString().trim();
    const fin      = finCita(row, zona);
    if (!fin) return false;

    const yaTerminada = ahora.getTime() >= fin.getTime() + ESPERA_POST_CITA_MIN * 60 * 1000;

    return estado === 'confirmada'
      && pendienteDeSolicitar(row.valoracion_solicitada)
      && telefono !== ''
      && !!row.event_id
      && yaTerminada;
  })
  .map(({ row, clinica }) => ({
    json: {
      ...row,
      eventId:        row.event_id,
      telefono:       row.telefono.toString(),
      // Lo lee el nodo "Enviar solicitud valoracion".
      phoneNumberId:  clinica.telefono_whatsapp_id,
      clinicaNombre:  clinica.nombre,
      respuesta: 'Hola ' + (row.nombre || '') + ', esperamos que tu visita a '
        + (clinica.nombre || 'la clinica') + ' haya ido muy bien. '
        + 'Podrias valorar tu experiencia del 1 al 5 estrellas? '
        + 'Si quieres, puedes anadir un comentario. Ej: 5 Todo genial'
    }
  }));
